using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Xml.Linq;
using QuietCare;

internal static class AdvancedTests {
    static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
    static void Reject(Action action){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,"Expected rejection");}
    static BoostProcess App(int id,string name="backgroundapp",double cpu=10){return new BoostProcess{App=new AppProcess{Id=id,Name=name,Path="C:\\TestApps\\"+name+".exe",Bytes=100*1024*1024,Started=DateTime.UtcNow.AddHours(-1)},CpuMs=cpu};}
    static BoostProcess Copy(BoostProcess value){return new BoostProcess{App=new AppProcess{Id=value.App.Id,Name=value.App.Name,Path=value.App.Path,Bytes=value.App.Bytes,Started=value.App.Started},CpuMs=value.CpuMs,CommandLine=value.CommandLine,VisibleWindow=value.VisibleWindow,BackgroundPriority=value.BackgroundPriority};}
    static string Reason(BoostProcess first,BoostProcess second,AudioActivity audio=null,ISet<int> ids=null,ISet<string> names=null,ISet<string> extra=null){return BoostPolicy.Reason(first,second,ids??new HashSet<int>(),names??new HashSet<string>(StringComparer.OrdinalIgnoreCase),audio??new AudioActivity{Verified=true},extra??new HashSet<string>(StringComparer.OrdinalIgnoreCase),-1);}
    sealed class FakeHost : IBoostRuntime,IBoostMeasurements,IBoostReadiness {
        public List<BoostProcess> Items=new List<BoostProcess>();public List<int> Trimmed=new List<int>();public int Active=0,FailId=-1;public bool Reduce=true;public string FreshReason;public bool AudioKnown=true;public HashSet<int> Media=new HashSet<int>();
        public long? WorkingSet(AppProcess p){return Trimmed.Contains(p.Id)&&Reduce?1024:p.Bytes;}public string Recheck(BoostProcess p,bool background){return FreshReason;}
        public List<BoostProcess> Capture(){return Items.Select(Copy).ToList();}public int Foreground(){return Active;}public AudioActivity Audio(){var a=new AudioActivity{Verified=AudioKnown};a.ActiveProcesses.UnionWith(Media);return a;}public void Trim(AppProcess p){if(p.Id==FailId)throw new IOException("Process became unavailable");Trimmed.Add(p.Id);}public ulong Available(){return 2UL*1024*1024*1024;}
    }
    sealed class FixtureHost : IBoostRuntime,IBoostMeasurements {
        readonly int pid;readonly WindowsBoostRuntime native=new WindowsBoostRuntime();public FixtureHost(int id){pid=id;}
        public long? WorkingSet(AppProcess app){return native.WorkingSet(app);}
        public List<BoostProcess> Capture(){return native.Capture().Where(x=>x.App.Id==pid).ToList();}public int Foreground(){return 0;}public AudioActivity Audio(){return native.Audio();}public ulong Available(){return native.Available();}public void Trim(AppProcess p){if(p.Id!=pid)throw new Exception("Test attempted to trim a non-fixture process");native.Trim(p);}
    }
    public static void Run(string fixture,Action<string,Action> test) {
        test("Idle polling stops for hidden or minimized main window",()=>{Check(!MonitorPolicy.Active(false,false,false,false),"Hidden app polls");Check(!MonitorPolicy.Active(true,true,false,false),"Minimized app polls");Check(MonitorPolicy.Active(false,false,true,false),"Widget should poll");Check(!MonitorPolicy.Active(true,false,true,true),"Suspend should stop polling");});
        test("Compact sampling leaves disk and network uncollected",()=>{using(var t=new Telemetry()){var s=t.Sample(false);Check(!s.DiskRead.HasValue&&!s.DiskWrite.HasValue&&!s.Download.HasValue&&!s.Upload.HasValue,"Detail counters collected");t.Dispose();Reject(()=>t.Sample());}});
        test("GPU aggregation rejects malformed, null and non-finite values",()=>{var values=new[]{new KeyValuePair<string,double>(null,99),new KeyValuePair<string,double>("luid_A_phys_x_eng_0",99),new KeyValuePair<string,double>("luid_A_phys_0_eng_0_engtype_3D",40),new KeyValuePair<string,double>("luid_A_phys_0_eng_0_engtype_3D",15),new KeyValuePair<string,double>("luid_A_phys_1_eng_0_engtype_3D",30),new KeyValuePair<string,double>("luid_A_phys_0_eng_1_engtype_Copy",double.NaN)};Check(Telemetry.AggregateGpu(values)==55,"Malformed or independent engines counted incorrectly");});
        test("Non-finite settings recover to visible defaults",()=>{new Settings{WidgetOpacity=double.NaN,WidgetX=double.PositiveInfinity,WidgetY=double.NaN}.Save();var s=Settings.Load();Check(s.WidgetOpacity==0.48&&s.WidgetX==-1&&s.WidgetY==-1,"Non-finite settings survived");});
        test("Smart Boost exclusions persist literally",()=>{new Settings{BoostExclusions="myeditor.exe\nmy.renderer.exe",BoostBackgroundBrowsers=false}.Save();var s=Settings.Load();Check(s.ProtectedApps.Length==2&&s.ProtectedApps[1]=="my.renderer.exe"&&!s.BoostBackgroundBrowsers,"Exclusions lost");Check(BoostPolicy.Name("com.docker.backend")=="com.docker.backend","Dotted process name broken");});
        test("Changed quarantine content cannot be purged or restored",()=>{string p=Path.Combine(fixture,"Temp","tamper.tmp");File.WriteAllText(p,"original");File.SetLastWriteTimeUtc(p,DateTime.UtcNow.AddDays(-10));var cleaner=new Cleaner(Path.Combine(fixture,"Temp"),Path.Combine(fixture,"State","Recovery"));var item=cleaner.Scan(CancellationToken.None).Items.Single(x=>x.Path==p);var rec=cleaner.Quarantine(item);File.AppendAllText(rec.Stored,"changed");Reject(()=>cleaner.Purge(rec));Reject(()=>cleaner.Restore(rec));Check(File.Exists(rec.Stored),"Changed data lost");});
        test("Recovery metadata changes invalidate stale selection",()=>{string p=Path.Combine(fixture,"Temp","metadata.tmp");File.WriteAllText(p,"original");File.SetLastWriteTimeUtc(p,DateTime.UtcNow.AddDays(-10));var cleaner=new Cleaner(Path.Combine(fixture,"Temp"),Path.Combine(fixture,"State","Recovery"));var rec=cleaner.Quarantine(cleaner.Scan(CancellationToken.None).Items.Single(x=>x.Path==p));string meta=Path.ChangeExtension(rec.Stored,"xml");var doc=State.Read(meta);doc.Root.SetAttributeValue("bytes",999);State.Save(meta,doc);Reject(()=>cleaner.Purge(rec));Check(File.Exists(rec.Stored),"Recovery data lost");});
        test("Duplicate hashing detects changed size, cancellation and deadline",()=>{string path=Path.Combine(fixture,"hash.bin");File.WriteAllText(path,new string('z',8192));Reject(()=>FileFinder.HashChecked(path,1,CancellationToken.None,Stopwatch.StartNew()));var c=new CancellationTokenSource();c.Cancel();bool cancelled=false;try{FileFinder.HashChecked(path,8192,c.Token,Stopwatch.StartNew());}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Cancellation swallowed");Reject(()=>FileFinder.HashChecked(path,8192,CancellationToken.None,Stopwatch.StartNew(),-1));});
        test("Idle background process qualifies without user selection",()=>{var p=App(200001);Check(Reason(p,Copy(p))==null,"Idle process rejected");});
        test("Foreground process and application family are protected",()=>{var p=App(200002,"chrome");p.CommandLine="chrome.exe --type=renderer";Check(Reason(p,Copy(p),null,new HashSet<int>{p.App.Id})!=null,"Foreground PID allowed");Check(Reason(p,Copy(p),null,null,new HashSet<string>{"chrome"})!=null,"Foreground browser family allowed");});
        test("Project, terminal, trading and office tools are excluded",()=>{foreach(string name in new[]{"codex","node","python","dotnet","code","terminal64","powershell","excel","com.docker.backend","msedgewebview2"}){var p=App(200003,name);Check(Reason(p,Copy(p))!=null,"Protected process allowed: "+name);}});
        test("Busy, new and small processes are protected",()=>{var p=App(200004);var busy=Copy(p);busy.CpuMs+=21;Check(Reason(p,busy)!=null,"Busy allowed");p.App.Started=DateTime.UtcNow;Check(Reason(p,Copy(p))!=null,"New process allowed");p.App.Started=DateTime.UtcNow.AddHours(-1);p.App.Bytes=1024;Check(Reason(p,Copy(p))!=null,"Small allowed");});
        test("Visible applications and changed identities are protected",()=>{var p=App(200005);var next=Copy(p);next.VisibleWindow=true;Check(Reason(p,next)!=null,"Visible app allowed");next=Copy(p);next.App.Started=next.App.Started.AddSeconds(1);Check(Reason(p,next)!=null,"Reused identity allowed");});
        test("Inactive browser renderer qualifies, controllers and extensions do not",()=>{var p=App(200006,"chrome");p.CommandLine="chrome --type=renderer";Check(Reason(p,Copy(p))==null,"Idle renderer rejected");p.CommandLine="chrome --type=gpu-process";Check(Reason(p,Copy(p))!=null,"GPU process allowed");p.CommandLine="chrome --type=renderer --extension-process";Check(Reason(p,Copy(p))!=null,"Extension allowed");});
        test("Audio activity or uncertain media state protects apps",()=>{var p=App(200007);var audio=new AudioActivity{Verified=true};audio.ActiveProcesses.Add(p.App.Id);Check(Reason(p,Copy(p),audio)!=null,"Audio process allowed");Check(Reason(p,Copy(p),new AudioActivity{Verified=false})!=null,"Unverified audio allowed");});
        test("Custom app exclusions and Windows paths are protected",()=>{var p=App(200008,"myeditor");Check(Reason(p,Copy(p),null,null,null,new HashSet<string>{"myeditor"})!=null,"Custom protection ignored");p.App.Name="other";p.App.Path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"a.exe");Check(Reason(p,Copy(p))!=null,"Windows process allowed");});
        test("Core Audio activity can be read without recording audio",()=>{var audio=AudioActivity.Read();Check(audio.Verified,"Core Audio enumeration unavailable on this PC");Check(audio.ActiveProcesses.All(x=>x>0),"Invalid audio PID");Console.WriteLine("  AUDIO activity enumeration verified; no audio content captured.");});
        test("Smart Boost trims qualifying processes and enforces cooldown",()=>{var host=new FakeHost();host.Items.Add(App(200010));var boost=new SmartBoost(host,()=>Task.FromResult(0));var r=boost.Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Trimmed==1&&host.Trimmed.Count==1,"Direct boost failed");Reject(()=>boost.Run(new string[0],CancellationToken.None).GetAwaiter().GetResult());});
        test("Smart Boost protects entire browser family playing audio",()=>{var host=new FakeHost();var renderer=App(200011,"chrome");renderer.CommandLine="--type=renderer";host.Items.Add(renderer);host.Items.Add(App(200012,"chrome"));host.Media.Add(200012);var r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Trimmed==0,"Audio browser family was trimmed");});
        test("Boost caps work, tolerates exited processes and supports cancellation",()=>{var host=new FakeHost();for(int i=0;i<20;i++)host.Items.Add(App(210000+i));host.FailId=210000;var r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Trimmed==12&&r.Failed==1,"Work cap or failure handling wrong");var c=new CancellationTokenSource();c.Cancel();var b=new SmartBoost(host,()=>Task.FromResult(0));Reject(()=>b.Run(new string[0],c.Token).GetAwaiter().GetResult());Check(!b.Busy,"Cancellation left boost busy");});
        test("Boost measures resident decreases and distinguishes accepted requests",()=>{var host=new FakeHost();host.Items.Add(App(220001));var r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Trimmed==1&&r.ObservedReductions==1&&r.Observations.Single().AfterBytes==1024,"Missing measured decrease");host=new FakeHost{Reduce=false};host.Items.Add(App(220002));r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Trimmed==1&&r.ObservedReductions==0&&r.Summary.Contains("No overall"),"Accepted request misreported as RAM freed");});
        test("Declined requests and protected processes have different feedback",()=>{var host=new FakeHost{FailId=220003};host.Items.Add(App(220003));var r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Eligible==1&&r.Failed==1&&r.Trimmed==0&&r.Summary.Contains("declined"),"Failure reported as no eligibility");host=new FakeHost();host.Items.Add(App(220004,"code"));r=new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();Check(r.Skipped==1&&r.SkipReasons["protected app / project tool"]==1&&r.Summary.Contains("qualified"),"Skip reasons missing");});
        test("Active browser option admits only idle background renderers",()=>{var host=new FakeHost{Active=220005};var controller=App(220005,"chrome");var renderer=App(220006,"chrome");renderer.CommandLine="--type=renderer";renderer.BackgroundPriority=true;host.Items.Add(controller);host.Items.Add(renderer);Func<bool,BoostResult> run=enabled=>new SmartBoost(host,()=>Task.FromResult(0)).Run(new string[0],CancellationToken.None,enabled).GetAwaiter().GetResult();Check(run(false).Trimmed==0,"Disabled option ignored");Check(run(true).Trimmed==1&&host.Trimmed.Single()==220006,"Background renderer did not qualify or foreground was touched");renderer.BackgroundPriority=false;Check(run(true).Trimmed==0,"Normal-priority active renderer qualified");renderer.BackgroundPriority=true;host.FreshReason="browser priority changed";Check(run(true).Trimmed==0,"Fresh protection ignored");host.FreshReason=null;host.Media.Add(controller.App.Id);Check(run(true).Trimmed==0,"Media browser not protected with option enabled");});
        test("Live isolated Boost preserves all allocated project data",()=>{
            string worker=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"MemoryFixture.exe");
            using(var p=Process.Start(new ProcessStartInfo(worker){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true}))try{
                Check(p.StandardOutput.ReadLine()=="READY","Fixture did not initialize");Thread.Sleep(5200);p.Refresh();long before=p.WorkingSet64;
                var result=new SmartBoost(new FixtureHost(p.Id)).Run(new string[0],CancellationToken.None).GetAwaiter().GetResult();p.Refresh();long after=p.WorkingSet64;Check(result.Trimmed==1&&result.ObservedReductions==1,"Fixture was not trimmed or decrease not measured");
                p.StandardInput.WriteLine("verify");Check(p.StandardOutput.ReadLine()=="PRESERVED","Allocated data changed");Check(p.WaitForExit(5000)&&p.ExitCode==0,"Fixture failed after trimming");
                Console.WriteLine("  LIVE fixture working set "+Format.Bytes(before)+" -> "+Format.Bytes(after)+"; all 96 MB of data preserved. No user app was trimmed by this test.");
            }finally{if(!p.HasExited)p.Kill();}
        });
    }
}
